    jal 0x8005a8e0 ; ROM+0x18024 | RAM 0x80030024 | WORD 0x0C016A38 | Call BIOS A0(39h) InitHeap BIOS wrapper; the delay slot runs before the BIOS vector dispatch
    lui a1, 0x0002 ; ROM+0x18028 | RAM 0x80030028 | WORD 0x3C050002 | Set a1 to the immediate shifted left 16 bits (0x0002 << 16)
    jal 0x80030798 ; ROM+0x1802C | RAM 0x8003002C | WORD 0x0C00C1E6 | Call to 0x80030798; the next instruction is the delay slot and RA = PC+8
    sll zero, zero, 0 ; ROM+0x18030 | RAM 0x80030030 | WORD 0x00000000 | No operation; registers and memory are unchanged
    lui at, 0x8008 ; ROM+0x18034 | RAM 0x80030034 | WORD 0x3C018008 | Set at to the immediate shifted left 16 bits (0x8008 << 16)
    sw v0, -0x6220(at) ; ROM+0x18038 | RAM 0x80030038 | WORD 0xAC229DE0 | Store word from v0 to [0x80079DE0] (value 0x00000000)
    lui at, 0x8008 ; ROM+0x1803C | RAM 0x8003003C | WORD 0x3C018008 | Set at to the immediate shifted left 16 bits (0x8008 << 16)
    addiu t6, zero, 4 ; ROM+0x18040 | RAM 0x80030040 | WORD 0x240E0004 | Set t6 to immediate 4 (0x4)
