    sw zero, -0x6218(at) ; ROM+0x1804C | RAM 0x8003004C | WORD 0xAC209DE8 | Store word from zero to [0x80079DE8] (value 0x00000000)
    lui at, 0x8008 ; ROM+0x18050 | RAM 0x80030050 | WORD 0x3C018008 | Set at to the immediate shifted left 16 bits (0x8008 << 16)
